/// Typed result of an explicit local activation/resume attempt.
///
/// `Retryable` always reports the durable lifecycle last observed after the
/// failure; `Blocked` preserves the enrollment's durable reason code. A handle
/// is returned only for `Active`, after bootstrap, backup, shadow proof,
/// `VerifiedLocal`, promotion, SQLite proof, and reconciliation-baseline open
/// have all completed.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SyncLocalActivationStatus {
    Active,
    Retryable {
        durable_stage: SyncLocalActivationStage,
        detail: String,
    },
    Blocked {
        reason_code: String,
    },
    UnsupportedOrIncompatible {
        component: SyncRuntimeComponent,
        scenario: ManagedStorageRefusalScenario,
    },
    CorruptOrUnreadable {
        component: SyncRuntimeComponent,
        scenario: ManagedStorageRefusalScenario,
    },
    AmbiguousOrForeignResidue {
        evidence: SyncAmbiguousEvidence,
        scenario: ManagedStorageRefusalScenario,
    },
}

/// Activation result, split from the retained runtime capability so callers
/// can persist or display failures without accidentally acquiring authority.
pub struct SyncLocalActivationResult {
    pub status: SyncLocalActivationStatus,
    pub handle: Option<SyncRuntimeHandle>,
}

impl fmt::Debug for SyncLocalActivationResult {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("SyncLocalActivationResult")
            .field("status", &self.status)
            .field("has_handle", &self.handle.is_some())
            .finish()
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncRuntimeComponent {
    Enrollment,
    Archive,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncNonActiveStage {
    ShadowImport,
    VerifiedLocal,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum SyncAmbiguousEvidence {
    EnrollmentResidue,
    EnrollmentNamespace,
    EnrollmentGraphBinding,
    ArchiveResidue,
    ArchiveNamespace,
    ArchiveBinding,
    /// The application-level opener found that the archive selected by the
    /// active runtime does not match the archive it was asked to open.
    ActiveArchiveMismatch,
}

/// Result of startup discovery and, only for a valid active result, actor open.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum SyncRuntimeOpenStatus {
    LegacyDefault,
    Absent,
    ExistingNonActive(SyncNonActiveStage),
    Blocked {
        reason_code: String,
    },
    UnsupportedOrIncompatible {
        component: SyncRuntimeComponent,
        scenario: ManagedStorageRefusalScenario,
    },
    CorruptOrUnreadable {
        component: SyncRuntimeComponent,
        scenario: ManagedStorageRefusalScenario,
    },
    AmbiguousOrForeignResidue {
        evidence: SyncAmbiguousEvidence,
        scenario: ManagedStorageRefusalScenario,
    },
    Active,
    OpenRefused {
        detail: String,
    },
    /// Pre-0.7 managed-storage state was discovered. It is not a runtime
    /// authority and not an error: the caller sets the private state aside and
    /// opens the graph in Direct Files.
    SupersededLegacyState,
}

impl SyncRuntimeOpenStatus {
    /// A retryable open has no scenario. A durable refusal always has one;
    /// markers emitted by lower storage boundaries survive the actor's bounded
    /// string transport and are recovered here rather than being discarded by
    /// the Tauri DTO conversion.
    pub fn durable_refusal_scenario(&self) -> Option<ManagedStorageRefusalScenario> {
        match self {
            Self::Blocked { reason_code } => Some(blocked_reason_scenario(reason_code)),
            Self::UnsupportedOrIncompatible { scenario, .. }
            | Self::CorruptOrUnreadable { scenario, .. }
            | Self::AmbiguousOrForeignResidue { scenario, .. } => Some(*scenario),
            Self::OpenRefused { detail } => ManagedStorageRefusalScenario::marked_in(detail),
            Self::LegacyDefault
            | Self::Absent
            | Self::ExistingNonActive(_)
            | Self::Active
            | Self::SupersededLegacyState => None,
        }
    }
}

impl SyncLocalActivationStatus {
    pub fn durable_refusal_scenario(&self) -> Option<ManagedStorageRefusalScenario> {
        match self {
            Self::Blocked { reason_code } => Some(blocked_reason_scenario(reason_code)),
            Self::UnsupportedOrIncompatible { scenario, .. }
            | Self::CorruptOrUnreadable { scenario, .. }
            | Self::AmbiguousOrForeignResidue { scenario, .. } => Some(*scenario),
            Self::Active | Self::Retryable { .. } => None,
        }
    }
}

fn blocked_reason_scenario(reason_code: &str) -> ManagedStorageRefusalScenario {
    ManagedStorageRefusalScenario::for_blocked_reason(reason_code).unwrap_or(
        // A syntactically valid blocked code not understood by this build is
        // retained evidence from a newer/different protocol, not permission to
        // guess at recovery.
        ManagedStorageRefusalScenario::ProtocolIncompatible,
    )
}

/// Startup returns typed status separately from the optional channel handle.
