    /// A public request may be too large to retain verbatim, but that never
    /// makes its observation disposable. The actor's one-owner queue already
    /// gives this marker an epoch, status visibility, and a full graph scan
    /// before the Safe handoff barrier can pass.
    fn retain_rejected_watcher_work(&self) -> Result<(), SyncRuntimeRequestError> {
        let (reply_sender, reply_receiver) = mpsc::channel();
        self.send(ActorRequest::Observe {
            observations: vec![SyncWatcherObservation::RescanRequired],
            reply: reply_sender,
        })?;
        reply_receiver
            .recv()
            .map_err(|_| SyncRuntimeRequestError::ActorUnavailable)?
    }

    pub fn tick(&self) -> Result<SyncRuntimeTick, SyncRuntimeRequestError> {
        let _operation = self.inner.operation.lock().unwrap();
        let (reply_sender, reply_receiver) = mpsc::channel();
        self.send(ActorRequest::Tick {
            reply: reply_sender,
        })?;
        reply_receiver
            .recv()
            .map_err(|_| SyncRuntimeRequestError::ActorUnavailable)
    }

    pub fn status(&self) -> Result<SyncRuntimeStatusSnapshot, SyncRuntimeRequestError> {
        let _operation = self.inner.operation.lock().unwrap();
        let sender_present = self.inner.sender.lock().unwrap().is_some();
        if !sender_present {
            return Ok(self.inner.status.read().unwrap().clone());
        }
        let (reply_sender, reply_receiver) = mpsc::channel();
        self.send(ActorRequest::Status {
            reply: reply_sender,
        })?;
        reply_receiver
            .recv()
            .map_err(|_| SyncRuntimeRequestError::ActorUnavailable)
    }

    /// Structured tier-2/tier-3 absence-sweep notifications retained by the
    /// actor. This is the packet C-4 backend surface; user-visible presentation
    /// intentionally lands with C-5 once Restore is executable.
    pub fn absence_sweep_events(
        &self,
    ) -> Result<Vec<SyncAbsenceSweepEvent>, SyncRuntimeRequestError> {
        let _operation = self.inner.operation.lock().unwrap();
        let (reply_sender, reply_receiver) = mpsc::channel();
        self.send(ActorRequest::AbsenceSweepEvents {
            reply: reply_sender,
        })?;
        reply_receiver
            .recv()
            .map_err(|_| SyncRuntimeRequestError::ActorUnavailable)
    }

    /// Subscribe to changed durable sweep snapshots. The receiver is
    /// observational: dropping it changes no sweep state and the actor prunes
    /// the disconnected subscriber on its next notification.
    pub fn subscribe_absence_sweep_events(
        &self,
    ) -> Result<Receiver<SyncAbsenceSweepEvent>, SyncRuntimeRequestError> {
        let _operation = self.inner.operation.lock().unwrap();
        let (event_sender, event_receiver) = mpsc::channel();
        let (reply_sender, reply_receiver) = mpsc::channel();
        self.send(ActorRequest::SubscribeAbsenceSweepEvents {
            events: event_sender,
            reply: reply_sender,
        })?;
        reply_receiver
            .recv()
            .map_err(|_| SyncRuntimeRequestError::ActorUnavailable)?;
        Ok(event_receiver)
    }

    pub fn reapply_absence_sweep(
        &self,
        sweep_id: &str,
    ) -> Result<SyncAbsenceSweepActionOutcome, SyncRuntimeRequestError> {
        let sweep_id = uuid::Uuid::parse_str(sweep_id)
            .map_err(|error| SyncRuntimeRequestError::InvalidRequest(error.to_string()))?;
        let _operation = self.inner.operation.lock().unwrap();
        let (reply_sender, reply_receiver) = mpsc::channel();
        self.send(ActorRequest::ReapplyAbsenceSweep {
            sweep_id,
            reply: reply_sender,
        })?;
        reply_receiver
            .recv()
            .map_err(|_| SyncRuntimeRequestError::ActorUnavailable)?
    }

