enum PendingManagedLocalCommit {
    Projection(TrustedLocalCommittedPendingProjection),
    Overlay(TrustedLocalCommittedRecovery),
    Response(TrustedLocalCommitted),
}

/// Parser-owned sparse input retained for one exact, not-yet-materialized page.
///
/// Every block contributes only immutable structure. Raw parser input and UUID
/// identity are retained only for blocks selected by the exact canonical task
/// marker index, so a later query never has to copy or scan the whole hot page.
#[derive(Clone, Debug)]
struct LatestTaskQueryOverlayPage {
    page_id: PageId,
    name: String,
    path: ManagedPath,
    kind: ManagedTextKind,
    format: Format,
    #[cfg(test)]
    preamble: Option<String>,
    structures: BTreeMap<BlockId, LatestTaskQueryOverlayStructure>,
    candidates: BTreeMap<BlockId, LatestTaskQueryOverlayCandidate>,
    candidate_ids_by_marker: BTreeMap<String, Vec<BlockId>>,
}

#[derive(Clone, Debug)]
struct LatestTaskQueryOverlayStructure {
    parent: Option<BlockId>,
    order: String,
}

#[derive(Clone, Debug)]
struct LatestTaskQueryOverlayCandidate {
    raw: String,
    logseq_uuid: Option<LogseqUuid>,
}

/// Every locally newest projection frame has one entry.  An incomplete entry
/// is authority too: it prevents a later sparse reader from accidentally
/// combining a stale SQLite row with a hot frame it cannot fully re-evaluate.
#[derive(Clone, Debug)]
enum LatestTaskQueryOverlayState {
    Complete(LatestTaskQueryOverlayPage),
    Incomplete,
}

#[derive(Clone, Debug)]
struct LatestTaskQueryOverlayEntry {
    sequence: u64,
    path: ManagedPath,
    state: LatestTaskQueryOverlayState,
}

/// Rebuildable point indexes over the uncheckpointed local journal. A record
/// is decoded once when recovered/appended, then ordinary derivative turns
/// answer batch and successor questions without rescanning or redecoding the
/// queue prefix.
#[derive(Default)]
struct ManagedLocalPendingIndex {
    records_by_batch: BTreeMap<BatchId, ManagedLocalRecord>,
    projection_targets: BTreeMap<(String, PageId), BTreeMap<u64, Option<Vec<u8>>>>,
    projection_sequences_by_digest: BTreeMap<(String, PageId, ContentDigest), BTreeSet<u64>>,
}

impl ManagedLocalPendingIndex {
    fn insert(&mut self, record: ManagedLocalRecord) -> Result<(), String> {
        let batch_id = record.prepared_batch().manifest().batch_id();
        let sequence = record.sequence();
        if self.records_by_batch.contains_key(&batch_id) {
            return Err(format!("duplicate pending managed-local batch {batch_id}"));
        }
        let mut entries = Vec::with_capacity(record.projections().len());
        let mut record_keys = BTreeSet::new();
        for projection in record.projections() {
            let intent = projection.intent();
            let bytes = intent.target().bytes();
            let key = (intent.path().as_str().to_owned(), intent.page_id());
            if !record_keys.insert(key.clone())
                || self
                    .projection_targets
                    .get(&key)
                    .is_some_and(|targets| targets.contains_key(&sequence))
            {
                return Err(format!(
                    "duplicate pending managed-local projection at sequence {sequence}"
                ));
            }
            entries.push((
                key,
                bytes.map(|bytes| bytes.to_vec()),
                bytes.map(ContentDigest::of),
            ));
        }
        for (key, bytes, digest) in entries {
            self.projection_targets
                .entry(key.clone())
                .or_default()
                .insert(sequence, bytes);
            if let Some(digest) = digest {
                self.projection_sequences_by_digest
                    .entry((key.0, key.1, digest))
                    .or_default()
                    .insert(sequence);
            }
        }
        self.records_by_batch.insert(batch_id, record);
        Ok(())
    }

    fn remove(&mut self, record: &ManagedLocalRecord) -> Result<(), String> {
        let batch_id = record.prepared_batch().manifest().batch_id();
        let sequence = record.sequence();
        let indexed = self
            .records_by_batch
            .get(&batch_id)
            .ok_or_else(|| format!("pending managed-local batch {batch_id} is not indexed"))?;
        if indexed != record {
            return Err(format!(
                "pending managed-local batch {batch_id} differs from its index"
            ));
        }
        for projection in record.projections() {
            let intent = projection.intent();
            let bytes = intent.target().bytes();
            let key = (intent.path().as_str().to_owned(), intent.page_id());
            if self
                .projection_targets
                .get(&key)
                .and_then(|targets| targets.get(&sequence))
                .is_none_or(|target| target.as_deref() != bytes)
            {
                return Err("pending projection target index differs from its record".into());
            }
            if let Some(bytes) = bytes {
                let digest_key = (key.0, key.1, ContentDigest::of(bytes));
                if self
                    .projection_sequences_by_digest
                    .get(&digest_key)
                    .is_none_or(|sequences| !sequences.contains(&sequence))
                {
                    return Err("pending projection digest index differs from its record".into());
                }
            }
        }
        self.records_by_batch.remove(&batch_id);
        for projection in record.projections() {
            let intent = projection.intent();
            let bytes = intent.target().bytes();
            let key = (intent.path().as_str().to_owned(), intent.page_id());
            let targets = self
                .projection_targets
                .get_mut(&key)
                .expect("validated above");
            targets.remove(&sequence);
            if targets.is_empty() {
                self.projection_targets.remove(&key);
            }
            if let Some(bytes) = bytes {
                let digest_key = (key.0, key.1, ContentDigest::of(bytes));
                let sequences = self
                    .projection_sequences_by_digest
                    .get_mut(&digest_key)
                    .expect("validated above");
                sequences.remove(&sequence);
                if sequences.is_empty() {
                    self.projection_sequences_by_digest.remove(&digest_key);
                }
            }
        }
        Ok(())
    }

    fn record(&self, batch_id: BatchId) -> Option<&ManagedLocalRecord> {
        self.records_by_batch.get(&batch_id)
    }
}

impl ManagedLocalSuccessorIndex for ManagedLocalPendingIndex {
    fn observe_successor(
        &self,
        path: &ManagedPath,
        page_id: PageId,
        after_sequence: u64,
        current: &[u8],
    ) -> ManagedLocalSuccessorObservation {
        let key = (path.as_str().to_owned(), page_id);
        let latest_sequence = self
            .projection_targets
            .get(&key)
            .and_then(|targets| targets.keys().next_back().copied())
            .filter(|sequence| *sequence > after_sequence);
        let current_matches_target = self
            .projection_sequences_by_digest
            .get(&(key.0.clone(), key.1, ContentDigest::of(current)))
            .and_then(|sequences| {
                sequences
                    .range((
                        std::ops::Bound::Excluded(after_sequence),
                        std::ops::Bound::Unbounded,
                    ))
                    .next_back()
                    .copied()
            })
            .and_then(|sequence| {
                self.projection_targets
                    .get(&key)
                    .and_then(|targets| targets.get(&sequence))
            })
            .is_some_and(|target| target.as_deref() == Some(current));
        ManagedLocalSuccessorObservation {
            latest_sequence,
            current_matches_target,
        }
    }
}

struct ManagedLocalRuntimeState {
    directory: Dir,
    journal: ManagedLocalJournal<ManagedLocalJournalPayloadKind>,
    frames: VecDeque<LocalJournalFrame<ManagedLocalJournalPayloadKind>>,
    pending_index: ManagedLocalPendingIndex,
    latest_projection_frames: BTreeMap<String, LocalJournalFrame<ManagedLocalJournalPayloadKind>>,
    latest_task_query_overlay: BTreeMap<String, LatestTaskQueryOverlayEntry>,
    checkpoint: ManagedLocalDrainCheckpoint,
    checkpoint_batch_id: Option<BatchId>,
    continuation: Option<ManagedLocalDrainContinuation>,
    pending_commit: Option<PendingManagedLocalCommit>,
    last_failure: Option<String>,
    /// Cleanup is cold, bounded work.  A settled managed-local runtime must
    /// never re-enumerate its history on ordinary idle ticks or saves.
    cleanup_pending: bool,
}

const MOVE_EPISODE_SCHEMA_VERSION: u32 = 2;
const MOVE_EPISODE_RECORD_MAX_BYTES: u64 = 16 * 1024;
const MOVE_EPISODE_CLEANUP_PER_TURN: usize = 32;
const MOVE_EPISODE_SCAN_ENTRIES_PER_TURN: usize = 128;
const MOVE_EPISODE_CLEANUP_QUEUE_LIMIT: usize = 256;
const RECENT_ACKNOWLEDGED_MOVE_EPISODES: usize = 256;

/// Immutable private binding from one caller episode to the actor-derived
/// batch identity and exact request digest. It is published before authoring,
/// so an uncertain acknowledgement can never make a repeated episode append a
/// semantically different transaction.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct ApplicationMoveEpisodeRecord {
    schema_version: u32,
    workspace_id: WorkspaceId,
    lineage_digest: LineageDigest,
    episode_id: Uuid,
    request_digest: ContentDigest,
    batch_id: BatchId,
    source_page_id: PageId,
    destination_page_id: PageId,
    transaction_fingerprint: ContentDigest,
    manifest_fingerprint: ContentDigest,
}

impl ApplicationMoveEpisodeRecord {
    fn filename(&self) -> String {
        format!("episode-{}.bin", self.episode_id.simple())
    }

    fn completion_filename(&self) -> String {
        format!("episode-{}.complete", self.episode_id.simple())
    }

    fn completion_bytes(&self) -> Result<Vec<u8>, SyncApplicationPageRequestError> {
        let record = self.encode()?;
        postcard::to_allocvec(&(
            b"tine/application-move-episode-complete/v1".as_slice(),
            self.episode_id,
            ContentDigest::of(&record),
        ))
        .map_err(|_| {
            SyncApplicationPageRequestError::ActorRefusedAt("move_episode_complete_encode")
        })
    }

    fn encode(&self) -> Result<Vec<u8>, SyncApplicationPageRequestError> {
        postcard::to_allocvec(self)
            .map_err(|_| SyncApplicationPageRequestError::ActorRefusedAt("move_episode_encode"))
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct ApplicationMoveEpisodeAcknowledgement {
    workspace_id: WorkspaceId,
    lineage_digest: LineageDigest,
    episode_id: Uuid,
    batch_id: BatchId,
}

impl ApplicationMoveEpisodeAcknowledgement {
    fn from_record(record: &ApplicationMoveEpisodeRecord) -> Self {
        Self {
            workspace_id: record.workspace_id,
            lineage_digest: record.lineage_digest,
            episode_id: record.episode_id,
            batch_id: record.batch_id,
        }
    }

    fn filename(&self) -> String {
        format!("episode-{}.acknowledged", self.episode_id.simple())
    }

    fn encode(&self) -> Result<Vec<u8>, SyncApplicationPageRequestError> {
        postcard::to_allocvec(self)
            .map_err(|_| SyncApplicationPageRequestError::ActorRefusedAt("move_episode_ack_encode"))
    }
}

#[derive(Clone)]
struct ApplicationMoveEpisodeDraft {
    workspace_id: WorkspaceId,
    lineage_digest: LineageDigest,
    episode_id: Uuid,
    request_digest: ContentDigest,
    batch_id: BatchId,
    source_page_id: PageId,
    destination_page_id: PageId,
    transaction_fingerprint: ContentDigest,
}

impl ApplicationMoveEpisodeDraft {
    fn finish(&self, manifest_fingerprint: ContentDigest) -> ApplicationMoveEpisodeRecord {
        ApplicationMoveEpisodeRecord {
            schema_version: MOVE_EPISODE_SCHEMA_VERSION,
            workspace_id: self.workspace_id,
            lineage_digest: self.lineage_digest,
            episode_id: self.episode_id,
            request_digest: self.request_digest,
            batch_id: self.batch_id,
            source_page_id: self.source_page_id,
            destination_page_id: self.destination_page_id,
            transaction_fingerprint: self.transaction_fingerprint,
            manifest_fingerprint,
        }
    }
}

enum ApplicationMoveEpisodeLookup {
    Missing,
    Pending(ApplicationMoveEpisodeRecord),
    Complete(ApplicationMoveEpisodeRecord),
}

fn persist_application_move_episode(
    directory: &Dir,
    record: &ApplicationMoveEpisodeRecord,
    fail_after_record_write_for_test: bool,
) -> Result<(), String> {
    let publication = DurableDirectoryPublication::open(directory)
        .map_err(|error| format!("move episode publication open failed: {error}"))?;
    let name = record.filename();
    let bytes = record.encode().map_err(|error| error.to_string())?;
    match read_optional_regular(directory, &name, MOVE_EPISODE_RECORD_MAX_BYTES, None)
        .map_err(|error| format!("move episode record read failed: {error}"))?
    {
        Some(existing) if existing == bytes => {}
        Some(_) => return Err("move episode immutable record collision".into()),
        None => {
            // Move episodes live below this process's private application
            // runtime root and are published only by its single actor.  On
            // Android the shared-archive hard-link protocol is unavailable;
            // use the same proven-absent, same-directory atomic publication
            // contract as the other private runtime journals.
            publication
                .publish_new_exact_single_writer(&name, &bytes)
                .map_err(|error| format!("move episode record publication failed: {error}"))?;
            if fail_after_record_write_for_test {
                // Model an error returned after the new directory entry became
                // readable but before the caller acquired a successful durable
                // publication acknowledgement. The completion proof is not
                // written, so this attempt can never proceed to the manifest.
                return Err("injected move episode directory-sync failure".into());
            }
        }
    }
    let completion_name = record.completion_filename();
    let completion_bytes = record
        .completion_bytes()
        .map_err(|error| error.to_string())?;
    publication
        .publish_new_exact_single_writer(&completion_name, &completion_bytes)
        .map_err(|error| format!("move episode completion publication failed: {error}"))?;
    let retained = read_optional_regular(
        directory,
        &completion_name,
        MOVE_EPISODE_RECORD_MAX_BYTES,
        None,
    )
    .map_err(|error| format!("move episode completion read failed: {error}"))?
    .ok_or_else(|| "move episode completion proof is missing".to_owned())?;
    if retained != completion_bytes {
        return Err("move episode completion proof collision".into());
    }
    Ok(())
}

impl ManagedLocalRuntimeState {
    fn pending_count(&self) -> usize {
        self.frames.len()
    }

    fn stage(&self) -> Option<String> {
        if self.pending_commit.is_some() {
            return Some("committed_foreground_recovery".into());
        }
        self.continuation
            .as_ref()
            .map(|continuation| format!("{:?}", continuation.stage()).to_ascii_lowercase())
            .or_else(|| (!self.frames.is_empty()).then(|| "authenticate".into()))
    }

    fn note_latest_projection_frame(
        &mut self,
        path: ManagedPath,
        frame: LocalJournalFrame<ManagedLocalJournalPayloadKind>,
    ) {
        let key = path.as_str().to_owned();
        self.latest_projection_frames
            .insert(key.clone(), frame.clone());
        self.latest_task_query_overlay.insert(
            key,
            LatestTaskQueryOverlayEntry {
                sequence: frame.sequence(),
                path,
                state: LatestTaskQueryOverlayState::Incomplete,
            },
        );
    }

    fn install_latest_task_query_overlay(
        &mut self,
        sequence: u64,
        page: LatestTaskQueryOverlayPage,
    ) {
        let key = page.path.as_str().to_owned();
        if self
            .latest_projection_frames
            .get(&key)
            .is_some_and(|frame| frame.sequence() == sequence)
            && self
                .latest_task_query_overlay
                .get(&key)
                .is_some_and(|entry| entry.sequence == sequence)
        {
            self.latest_task_query_overlay.insert(
                key,
                LatestTaskQueryOverlayEntry {
                    sequence,
                    path: page.path.clone(),
                    state: LatestTaskQueryOverlayState::Complete(page),
                },
            );
        }
    }

    fn retire_latest_task_query_overlay(&mut self, path: &ManagedPath, sequence: u64) {
        let key = path.as_str();
        if self
            .latest_task_query_overlay
            .get(key)
            .is_some_and(|entry| entry.sequence == sequence)
        {
            self.latest_task_query_overlay.remove(key);
        }
    }

    fn compact_clean_foreground_journal_if_needed(&mut self) -> Result<bool, String> {
        if self.cleanup_pending {
            self.retry_clean_foreground_history_cleanup()?;
        }
        if !self.frames.is_empty() || self.pending_commit.is_some() {
            return Ok(false);
        }
        if self.checkpoint.next_sequence() != self.journal.next_sequence() {
            return Err("clean foreground compaction checkpoint is not current".into());
        }
        let suffix_frames = self
            .journal
            .next_sequence()
            .checked_sub(self.journal.base_sequence())
            .ok_or_else(|| "clean foreground journal sequence is before its base".to_owned())?;
        if suffix_frames < MANAGED_LOCAL_COMPACTION_FRAME_THRESHOLD {
            return Ok(false);
        }
        let generation = self.journal.selector_generation();
        let successor_generation = generation
            .checked_add(1)
            .ok_or_else(|| "clean foreground selector generation overflow".to_owned())?;
        let accepted_batch_id = self.checkpoint_batch_id.ok_or_else(|| {
            "clean foreground checkpoint has no accepted batch binding".to_owned()
        })?;
        let (successor, _) = prepare_clean_foreground_journal(
            &self.directory,
            self.checkpoint.clone(),
            Some(accepted_batch_id),
            successor_generation,
        )?;
        let predecessor = std::mem::replace(&mut self.journal, successor);
        drop(predecessor);
        self.cleanup_pending = true;
        self.retry_clean_foreground_history_cleanup()?;
        Ok(true)
    }

    fn retry_clean_foreground_history_cleanup(&mut self) -> Result<(), String> {
        if !self.cleanup_pending {
            return Ok(());
        }
        let retained_generation = self.journal.selector_generation();
        self.cleanup_clean_foreground_history(retained_generation)?;
        self.cleanup_pending = false;
        Ok(())
    }

    fn cleanup_clean_foreground_history(&self, retained_generation: u64) -> Result<(), String> {
        let names = clean_foreground_journal_names(&self.directory)?;
        let device_id = self.checkpoint.device_id();
        for (generation, anchor_name) in names.iter().filter_map(|name| {
            parse_managed_local_v2_anchor_name(name, device_id)
                .map(|generation| (generation, name.clone()))
        }) {
            if generation >= retained_generation {
                continue;
            }
            let bytes = read_optional_regular(
                &self.directory,
                &anchor_name,
                MANAGED_LOCAL_ANCHOR_V2_BYTES as u64,
                None,
            )
            .map_err(|error| {
                format!("cannot read retired clean foreground anchor {anchor_name}: {error}")
            })?
            .ok_or_else(|| format!("clean foreground anchor {anchor_name} disappeared"))?;
            let anchor = ManagedLocalGenerationAnchorV2::decode(
                &bytes,
                generation,
                self.checkpoint.workspace_id(),
                self.checkpoint.lineage_digest(),
                device_id,
            )
            .map_err(|error| {
                format!("retired clean foreground anchor {anchor_name} is invalid: {error}")
            })?;
            self.directory.remove_file(&anchor_name).map_err(|error| {
                format!("cannot retire clean foreground anchor {anchor_name}: {error}")
            })?;
            for tuple_name in [
                anchor.selection().segment_name(),
                anchor.selection().frontier_name(),
            ] {
                if let Err(error) = self.directory.remove_file(tuple_name) {
                    if error.kind() != std::io::ErrorKind::NotFound {
                        return Err(format!(
                            "cannot retire clean foreground tuple {tuple_name}: {error}"
                        ));
                    }
                }
            }
        }
        for name in names {
            if clean_foreground_checkpoint_sequence(&name)
                .is_some_and(|sequence| sequence <= self.checkpoint.next_sequence())
            {
                if let Err(error) = self.directory.remove_file(&name) {
                    if error.kind() != std::io::ErrorKind::NotFound {
                        return Err(format!(
                            "cannot retire clean foreground checkpoint {name}: {error}"
                        ));
                    }
                }
            }
        }
        let directory = self
            .directory
            .try_clone()
            .map_err(CleanOpenError::from)?
            .into_std_file();
        crate::durability_counters::sync_directory(&directory)
            .map_err(CleanOpenError::from)
            .map_err(String::from)
    }
}

fn latest_task_query_overlay_page_from_application(
    current: &ApplicationCurrentPage,
) -> Result<LatestTaskQueryOverlayPage, ()> {
    let parsed = flatten_application_blocks(&current.page.blocks);
    if parsed.len() != current.editor.dto.blocks.len()
        || parsed.len() != current.editor.blocks.len()
    {
        return Err(());
    }
    let materialized = current
        .editor
        .blocks
        .iter()
        .map(|block| (block.block_id, block))
        .collect::<HashMap<_, _>>();
    if materialized.len() != current.editor.blocks.len() {
        return Err(());
    }
    let mut structures = BTreeMap::new();
    let mut candidates = BTreeMap::new();
    let mut candidate_ids_by_marker = BTreeMap::<String, Vec<BlockId>>::new();
    for (index, parsed_block) in parsed.iter().enumerate() {
        let SyncEditorBlockKey::Existing(id) = &current.editor.dto.blocks[index].key else {
            return Err(());
        };
        let block_id = parse_editor_block_id(id).map_err(|_| ())?;
        let materialized = materialized.get(&block_id).ok_or(())?;
        if materialized.content != parsed_block.block.raw
            || !sparse_task_query_order_is_valid(&materialized.order)
            || structures
                .insert(
                    block_id,
                    LatestTaskQueryOverlayStructure {
                        parent: materialized.parent,
                        order: materialized.order.clone(),
                    },
                )
                .is_some()
        {
            return Err(());
        }
        if let Some(marker) = parsed_block.block.marker.as_deref() {
            let marker = marker.to_ascii_uppercase();
            if marker.is_empty()
                || candidates
                    .insert(
                        block_id,
                        LatestTaskQueryOverlayCandidate {
                            raw: parsed_block.block.raw.clone(),
                            logseq_uuid: materialized.logseq_uuid,
                        },
                    )
                    .is_some()
            {
                return Err(());
            }
            candidate_ids_by_marker
                .entry(marker)
                .or_default()
                .push(block_id);
        }
    }
    if structures.len() != materialized.len()
        || structures.values().any(|structure| {
            structure
                .parent
                .is_some_and(|parent| !structures.contains_key(&parent))
        })
    {
        return Err(());
    }
    Ok(LatestTaskQueryOverlayPage {
        page_id: current.editor.page.page_id,
        name: current.page.name.clone(),
        path: current.editor.page.path.clone(),
        kind: current.editor.page.kind,
        format: current.page.format,
        #[cfg(test)]
        preamble: current.page.pre_block.clone(),
        structures,
        candidates,
        candidate_ids_by_marker,
    })
}

const CLEAN_FOREGROUND_JOURNAL_WORKSPACE_PREFIX: &str = "clean-workspace";
const CLEAN_FOREGROUND_CHECKPOINT_BYTES: u64 = 16 * 1024;

fn clean_foreground_checkpoint_filename(next_sequence: u64) -> String {
    format!("checkpoint-{next_sequence:020}.bin")
}

fn clean_foreground_checkpoint_sequence(name: &str) -> Option<u64> {
    let digits = name.strip_prefix("checkpoint-")?.strip_suffix(".bin")?;
    if digits.len() != 20 || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    let sequence = digits.parse().ok()?;
    (format!("{sequence:020}") == digits).then_some(sequence)
}

fn persist_clean_foreground_checkpoint(
    directory: &Dir,
    checkpoint: &ManagedLocalDrainCheckpoint,
) -> Result<(), String> {
    let filename = clean_foreground_checkpoint_filename(checkpoint.next_sequence());
    let bytes = checkpoint.encode()?;
    match read_optional_regular(
        directory,
        &filename,
        CLEAN_FOREGROUND_CHECKPOINT_BYTES,
        None,
    )
    .map_err(|error| format!("cannot read clean foreground checkpoint {filename}: {error}"))?
    {
        Some(existing) if existing == bytes => Ok(()),
        Some(_) => Err(format!(
            "clean foreground checkpoint {filename} collides with different durable evidence"
        )),
        // This checkpoint directory is private to one local runtime actor.
        // Shared/provider namespaces must retain strict no-replace
        // publication, but this sole-writer namespace may use the Android-safe
        // proven-absent atomic-rename fallback.
        None => DurableDirectoryPublication::open(directory)
            .map_err(|error| {
                format!("clean foreground checkpoint publication is unavailable: {error}")
            })?
            .publish_new_exact_single_writer(&filename, &bytes)
            .map_err(|error| {
                format!("cannot publish clean foreground checkpoint {filename}: {error}")
            }),
    }
}

fn clean_foreground_journal_names(directory: &Dir) -> Result<Vec<String>, String> {
    let entries = directory
        .entries()
        .map_err(|error| format!("cannot enumerate clean foreground journal: {error}"))?;
    let mut names = Vec::new();
    for entry in entries {
        let entry = entry
            .map_err(|error| format!("cannot enumerate clean foreground journal entry: {error}"))?;
        if let Ok(name) = entry.file_name().into_string() {
            names.push(name);
        }
    }
    Ok(names)
}

fn prepare_clean_foreground_journal(
    directory: &Dir,
    checkpoint: ManagedLocalDrainCheckpoint,
    accepted_batch_id: Option<BatchId>,
    selector_generation: u64,
) -> Result<
    (
        ManagedLocalJournal<ManagedLocalJournalPayloadKind>,
        ManagedLocalGenerationAnchorV2,
    ),
    String,
> {
    let publication = DurableDirectoryPublication::open(directory)
        .map_err(|error| format!("clean foreground journal publication is unavailable: {error}"))?;
    let anchor = ManagedLocalGenerationAnchorV2::new(
        selector_generation,
        checkpoint,
        accepted_batch_id,
        Uuid::new_v4(),
    )
    .map_err(|error| format!("cannot construct clean foreground journal: {error}"))?;
    let anchor_name = managed_local_v2_anchor_name(
        anchor.checkpoint().device_id(),
        anchor.selector_generation(),
    );
    let anchor_bytes = anchor
        .encode()
        .map_err(|error| format!("cannot encode clean foreground journal anchor: {error}"))?;
    LocalJournalSegmentV2::<ManagedLocalJournalPayloadKind>::prepare_single_writer(
        directory,
        anchor.selection(),
    )
    .map_err(|error| format!("cannot prepare clean foreground journal segment: {error}"))?;
    let (journal, recovery) =
        LocalJournalSegmentV2::open_selected(directory, anchor.selection())
            .map_err(|error| format!("cannot open clean foreground journal segment: {error}"))?;
    if recovery.frames_recovered != 0
        || recovery.discarded_tail_bytes != 0
        || journal.next_sequence() != anchor.checkpoint().next_sequence()
    {
        return Err("fresh clean foreground journal is not empty".into());
    }
    publication
        .publish_new_exact_single_writer(&anchor_name, &anchor_bytes)
        .map_err(|error| {
            format!("cannot publish clean foreground journal anchor {anchor_name}: {error}")
        })?;
    Ok((
        ManagedLocalJournal::from_open(selector_generation, journal),
        anchor,
    ))
}

struct RecoveredCleanForegroundJournal {
    directory: Dir,
    journal: ManagedLocalJournal<ManagedLocalJournalPayloadKind>,
    checkpoint: ManagedLocalDrainCheckpoint,
    checkpoint_batch_id: Option<BatchId>,
    recovered_frames: Vec<LocalJournalFrame<ManagedLocalJournalPayloadKind>>,
    cleanup_pending: bool,
}

/// Select and decode the durable managed-local tail without requiring a graph,
/// engine, SQLite projection, or operation archive. Cold open uses this narrow
/// seam before archive validation so an undrained record can authorize repair
/// of exactly the content-addressed object bytes it still carries.
fn recover_clean_foreground_journal_only(
    application_runtime_root: &Path,
    binding: &ActorRuntimeBinding,
    create_if_absent: bool,
) -> Result<Option<RecoveredCleanForegroundJournal>, String> {
    if !application_runtime_root.exists() {
        if !create_if_absent {
            return Ok(None);
        }
        fs::create_dir_all(application_runtime_root)
            .map_err(|error| format!("cannot create clean foreground journal root: {error}"))?;
    }
    let root = Dir::open_ambient_dir(application_runtime_root, ambient_authority())
        .map_err(|error| format!("cannot retain clean foreground journal root: {error}"))?;
    ensure_directory_nofollow(&root, MANAGED_LOCAL_JOURNAL_NAMESPACE)
        .map_err(CleanOpenError::from)?;
    let namespace =
        open_dir_nofollow(&root, MANAGED_LOCAL_JOURNAL_NAMESPACE).map_err(CleanOpenError::from)?;
    let workspace_name = format!(
        "{CLEAN_FOREGROUND_JOURNAL_WORKSPACE_PREFIX}-{}-{}",
        binding.workspace_id(),
        binding.lineage_digest()
    );
    ensure_directory_nofollow(&namespace, &workspace_name).map_err(CleanOpenError::from)?;
    let directory = open_dir_nofollow(&namespace, &workspace_name).map_err(CleanOpenError::from)?;
    let device_id = binding.device_id().as_uuid();
    let names = clean_foreground_journal_names(&directory)?;
    let mut anchors = names
        .iter()
        .filter_map(|name| {
            parse_managed_local_v2_anchor_name(name, device_id)
                .map(|generation| (generation, name.clone()))
        })
        .collect::<Vec<_>>();
    anchors.sort_unstable_by_key(|(generation, _)| *generation);
    // A crash after publishing a successor but before retiring its predecessor
    // may leave multiple complete anchors. The greatest authenticated selector
    // is authoritative; lower selectors are redundant recovery history.
    let (journal, mut checkpoint, mut checkpoint_batch_id) = match anchors.pop() {
        Some((selector_generation, anchor_name)) => {
            let bytes = read_optional_regular(
                &directory,
                &anchor_name,
                MANAGED_LOCAL_ANCHOR_V2_BYTES as u64,
                None,
            )
            .map_err(|error| {
                format!("cannot read clean foreground journal anchor {anchor_name}: {error}")
            })?
            .ok_or_else(|| format!("clean foreground journal anchor {anchor_name} disappeared"))?;
            let anchor = ManagedLocalGenerationAnchorV2::decode(
                &bytes,
                selector_generation,
                binding.workspace_id(),
                binding.lineage_digest(),
                device_id,
            )
            .map_err(|error| {
                format!("clean foreground journal anchor {anchor_name} is invalid: {error}")
            })?;
            let (segment, _) = LocalJournalSegmentV2::open_selected(&directory, anchor.selection())
                .map_err(|error| {
                    format!("cannot open clean foreground journal {anchor_name}: {error}")
                })?;
            (
                ManagedLocalJournal::from_open(selector_generation, segment),
                anchor.checkpoint().clone(),
                anchor.accepted_batch_id(),
            )
        }
        None if !create_if_absent => return Ok(None),
        None => {
            let checkpoint = ManagedLocalDrainCheckpoint::initial(
                device_id,
                binding.workspace_id(),
                binding.lineage_digest(),
            );
            let (journal, anchor) =
                prepare_clean_foreground_journal(&directory, checkpoint, None, 1)?;
            (
                journal,
                anchor.checkpoint().clone(),
                anchor.accepted_batch_id(),
            )
        }
    };
    let mut recovered_frames = Vec::new();
    journal
        .replay(|frame| recovered_frames.push(frame))
        .map_err(|error| format!("cannot replay clean foreground journal: {error}"))?;
    if journal.base_sequence() != checkpoint.next_sequence()
        || journal
            .base_sequence()
            .checked_add(recovered_frames.len() as u64)
            != Some(journal.next_sequence())
    {
        return Err("clean foreground journal anchor/sequence binding is inconsistent".into());
    }

    let mut checkpoint_sequences = names
        .iter()
        .filter_map(|name| clean_foreground_checkpoint_sequence(name))
        .filter(|sequence| *sequence > checkpoint.next_sequence())
        .collect::<Vec<_>>();
    checkpoint_sequences.sort_unstable();
    checkpoint_sequences.dedup();
    let mut expected_checkpoint = checkpoint.next_sequence().saturating_add(1);
    for next_sequence in checkpoint_sequences {
        if next_sequence != expected_checkpoint || next_sequence > journal.next_sequence() {
            return Err(format!(
                "clean foreground checkpoint sequence is not a contiguous journal prefix: expected {expected_checkpoint}, found {next_sequence}"
            ));
        }
        let filename = clean_foreground_checkpoint_filename(next_sequence);
        let bytes = read_optional_regular(
            &directory,
            &filename,
            CLEAN_FOREGROUND_CHECKPOINT_BYTES,
            None,
        )
        .map_err(|error| format!("cannot read clean foreground checkpoint {filename}: {error}"))?
        .ok_or_else(|| format!("clean foreground checkpoint {filename} disappeared"))?;
        checkpoint = ManagedLocalDrainCheckpoint::decode(
            &bytes,
            device_id,
            binding.workspace_id(),
            binding.lineage_digest(),
        )
        .map_err(|error| format!("clean foreground checkpoint {filename} is invalid: {error}"))?;
        if checkpoint.next_sequence() != next_sequence {
            return Err(format!(
                "clean foreground checkpoint {filename} names sequence {}",
                checkpoint.next_sequence()
            ));
        }
        expected_checkpoint = next_sequence.saturating_add(1);
    }
    let checkpointed = checkpoint
        .next_sequence()
        .checked_sub(journal.base_sequence())
        .ok_or_else(|| "clean foreground checkpoint is behind its journal generation".to_owned())?;
    let checkpointed = usize::try_from(checkpointed)
        .map_err(|_| "clean foreground checkpoint exceeds addressable memory".to_owned())?;
    if checkpointed > recovered_frames.len() {
        return Err("clean foreground checkpoint is ahead of its journal generation".into());
    }
    for frame in &recovered_frames[..checkpointed] {
        let record =
            crate::oplog::decode_managed_local_record(frame).map_err(CleanOpenError::from)?;
        checkpoint_batch_id = Some(record.prepared_batch().manifest().batch_id());
    }
    let recovered_frames = recovered_frames.split_off(checkpointed);
    Ok(Some(RecoveredCleanForegroundJournal {
        directory,
        journal,
        checkpoint,
        checkpoint_batch_id,
        recovered_frames,
        cleanup_pending: !anchors.is_empty(),
    }))
}

fn clean_undrained_object_repair_coverage(
    application_runtime_root: &Path,
    binding: &ActorRuntimeBinding,
) -> Result<BTreeMap<ContentDigest, Vec<u8>>, String> {
    let Some(RecoveredCleanForegroundJournal {
        recovered_frames, ..
    }) = recover_clean_foreground_journal_only(application_runtime_root, binding, false)?
    else {
        return Ok(BTreeMap::new());
    };
    let mut covered = BTreeMap::<ContentDigest, Vec<u8>>::new();
    for frame in recovered_frames {
        let record = crate::oplog::decode_managed_local_record(&frame).map_err(|error| {
            format!(
                "clean foreground journal record {}:{} is invalid during archive repair pre-scan: {error}",
                frame.device_id(),
                frame.sequence()
            )
        })?;
        for object in record.prepared_batch().objects() {
            let bytes = object.encode().map_err(CleanOpenError::from)?;
            let digest = ContentDigest::of(&bytes);
            match covered.entry(digest) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    entry.insert(bytes);
                }
                std::collections::btree_map::Entry::Occupied(entry)
                    if entry.get().as_slice() == bytes.as_slice() => {}
                std::collections::btree_map::Entry::Occupied(_) => {
                    return Err(format!(
                        "undrained clean foreground records ambiguously cover object {digest}"
                    ));
                }
            }
        }
    }
    Ok(covered)
}

fn open_clean_foreground_journal(
    application_runtime_root: &Path,
    binding: &ActorRuntimeBinding,
    graph: &Graph,
    runtime: &mut CleanLocalRuntime,
) -> Result<ManagedLocalRuntimeState, String> {
    let RecoveredCleanForegroundJournal {
        directory,
        journal,
        checkpoint,
        checkpoint_batch_id,
        recovered_frames,
        cleanup_pending,
    } = recover_clean_foreground_journal_only(application_runtime_root, binding, true)?
        .ok_or_else(|| "clean foreground journal creation did not return a journal".to_owned())?;

    let mut latest_projection_frames = BTreeMap::new();
    let mut latest_task_query_overlay = BTreeMap::new();
    let mut pending_index = ManagedLocalPendingIndex::default();
    for frame in &recovered_frames {
        let record = crate::oplog::decode_managed_local_record(frame).map_err(|error| {
            format!(
                "clean foreground journal record {}:{} is invalid: {error}",
                frame.device_id(),
                frame.sequence()
            )
        })?;
        for projection in record.projections() {
            let path = projection.intent().path().clone();
            let key = path.as_str().to_owned();
            latest_projection_frames.insert(key.clone(), frame.clone());
            latest_task_query_overlay.insert(
                key,
                LatestTaskQueryOverlayEntry {
                    sequence: frame.sequence(),
                    path,
                    state: LatestTaskQueryOverlayState::Incomplete,
                },
            );
        }
        pending_index.insert(record)?;
    }
    if checkpoint.next_sequence() != 0 || !recovered_frames.is_empty() {
        let mut session = runtime
            .admit_clean_mutation(graph)
            .map_err(|error| format!("cannot authorize clean journal recovery: {error}"))?;
        let (_, engine, _) = session
            .parts()
            .map_err(|error| format!("cannot retain clean journal recovery engine: {error}"))?;
        engine
            .resume_checkpointed_managed_local_prefix(checkpoint.next_sequence())
            .map_err(|error| {
                format!(
                    "cannot restore clean foreground checkpoint sequence {}: {error}",
                    checkpoint.next_sequence()
                )
            })?;
        for frame in &recovered_frames {
            engine.replay_managed_local_record(frame).map_err(|error| {
                format!(
                    "cannot restore clean foreground journal record {}:{}: {error}",
                    frame.device_id(),
                    frame.sequence()
                )
            })?;
        }
    }
    Ok(ManagedLocalRuntimeState {
        directory,
        journal,
        frames: recovered_frames.into(),
        pending_index,
        latest_projection_frames,
        latest_task_query_overlay,
        checkpoint,
        checkpoint_batch_id,
        continuation: None,
        pending_commit: None,
        last_failure: None,
        cleanup_pending,
    })
}

/// One complete sparse input after the actor has proved the page identity and
/// structural ancestry.  It deliberately contains no page DTO or outline.
#[derive(Clone, Debug)]
struct ManagedSparseTaskQueryCandidate {
    block_id: BlockId,
    page_id: PageId,
    parent: Option<BlockId>,
    order: String,
    raw: String,
    identity: String,
    page: crate::query::ApplicationSparseQueryPage,
}

#[derive(Clone, Debug)]
struct ManagedSparseTaskQueryStructure {
    page_id: PageId,
    parent: Option<BlockId>,
    order: String,
}

/// Joined SQLite page facts are already authenticated by the certified
/// candidate read.  Cache them per page so a dense task page does one recency
/// metadata lookup rather than one per candidate block.
#[derive(Clone, Debug)]
struct ManagedSparseTaskQueryPageFacts {
    name: String,
    path: ManagedPath,
    kind: ManagedTextKind,
    sparse_page: crate::query::ApplicationSparseQueryPage,
}

#[derive(Clone, Copy, Debug, Default)]
struct ManagedSparseTaskQueryMetrics {
    candidate_rows: usize,
    ancestor_rows: usize,
    parser_rows: usize,
    overlay_rows: usize,
    sqlite_rows_fetched: usize,
    overlay_index_visits: usize,
    overlay_candidate_visits: usize,
    overlay_structure_lookups: usize,
    overlay_raw_bytes_cloned: usize,
    masked_page_fast_forwards: usize,
    dto_constructions: usize,
}

fn sparse_task_query_identity(block_id: BlockId, logseq_uuid: Option<LogseqUuid>) -> String {
    logseq_uuid.map_or_else(
        || format!("{SYNC_APPLICATION_INTERNAL_BLOCK_PREFIX}{block_id}"),
        |uuid| uuid.to_string(),
    )
}

fn sparse_task_query_page_kind(kind: ManagedTextKind) -> PageKind {
    match kind {
        ManagedTextKind::Page => PageKind::Page,
        ManagedTextKind::Journal => PageKind::Journal,
    }
}

fn sparse_task_query_page_recency(
    graph_root: &Path,
    journal_format: &crate::date::JournalFormat,
    name: &str,
    path: &ManagedPath,
    kind: ManagedTextKind,
) -> i64 {
    journal_format.page_recency_secs(
        kind == ManagedTextKind::Journal,
        name,
        &graph_root.join(path.as_str()),
    )
}

impl ManagedSparseTaskQueryPageFacts {
    fn from_joined_row(
        row: &MaterializedTaskCandidateBlockRow,
        graph_root: &Path,
        journal_format: &crate::date::JournalFormat,
    ) -> Result<Self, ManagedSparseTaskQueryFallback> {
        if LogicalPageName::parse(row.page_name.clone()).is_err() {
            return Err(ManagedSparseTaskQueryFallback::CandidateAuthority);
        }
        let format = Format::from_path(Path::new(row.page_path.as_str()));
        Ok(Self {
            name: row.page_name.clone(),
            path: row.page_path.clone(),
            kind: row.page_kind,
            sparse_page: crate::query::ApplicationSparseQueryPage {
                name: row.page_name.clone(),
                path: row.page_path.as_str().to_owned(),
                kind: sparse_task_query_page_kind(row.page_kind),
                is_org: format == Format::Org,
                recency: sparse_task_query_page_recency(
                    graph_root,
                    journal_format,
                    &row.page_name,
                    &row.page_path,
                    row.page_kind,
                ),
            },
        })
    }

    fn matches_joined_row(&self, row: &MaterializedTaskCandidateBlockRow) -> bool {
        self.name == row.page_name && self.path == row.page_path && self.kind == row.page_kind
    }
}

fn managed_sparse_task_query_candidate_from_sqlite(
    row: MaterializedTaskCandidateBlockRow,
    page: crate::query::ApplicationSparseQueryPage,
) -> ManagedSparseTaskQueryCandidate {
    ManagedSparseTaskQueryCandidate {
        block_id: row.block_id,
        page_id: row.page_id,
        parent: row.parent,
        order: row.order,
        raw: row.content,
        identity: sparse_task_query_identity(row.block_id, row.logseq_uuid),
        page,
    }
}

fn sparse_task_query_order_is_valid(order: &str) -> bool {
    !order.is_empty() && order.len() <= 512 && !order.chars().any(char::is_control)
}

fn sparse_task_query_dfs_key(leaf_to_root: Vec<(String, BlockId)>) -> Vec<String> {
    let mut root_to_leaf = leaf_to_root;
    root_to_leaf.reverse();
    root_to_leaf
        .into_iter()
        .flat_map(|(order, block_id)| {
            // `BlockId` derives `Ord` from `Uuid`; its canonical lower-case
            // hyphenated UUID spelling is fixed-width hexadecimal, so lexical
            // string order preserves that UUID order.  Keeping the two values
            // adjacent mirrors projection's `(order, block_id)` sibling key.
            [order, block_id.to_string()]
        })
        .collect()
}

fn sparse_task_query_dfs_order(
    candidate: &ManagedSparseTaskQueryCandidate,
    overlay_pages: &HashMap<PageId, &LatestTaskQueryOverlayPage>,
    read: &SqliteMaterializedRead<'_>,
    structure_cache: &mut HashMap<BlockId, ManagedSparseTaskQueryStructure>,
    metrics: &mut ManagedSparseTaskQueryMetrics,
) -> Result<Vec<String>, ManagedSparseTaskQueryFallback> {
    let mut seen = HashSet::new();
    let mut block_id = candidate.block_id;
    let mut structure = ManagedSparseTaskQueryStructure {
        page_id: candidate.page_id,
        parent: candidate.parent,
        order: candidate.order.clone(),
    };
    let mut leaf_to_root = Vec::new();
    loop {
        if !seen.insert(block_id)
            || structure.page_id != candidate.page_id
            || !sparse_task_query_order_is_valid(&structure.order)
        {
            return Err(ManagedSparseTaskQueryFallback::Structure);
        }
        leaf_to_root.push((structure.order.clone(), block_id));
        let Some(parent) = structure.parent else {
            break;
        };
        block_id = parent;
        structure = if let Some(page) = overlay_pages.get(&candidate.page_id) {
            metrics.overlay_structure_lookups = metrics.overlay_structure_lookups.saturating_add(1);
            let structure = page
                .structures
                .get(&parent)
                .ok_or(ManagedSparseTaskQueryFallback::Structure)?;
            ManagedSparseTaskQueryStructure {
                page_id: candidate.page_id,
                parent: structure.parent,
                order: structure.order.clone(),
            }
        } else {
            if let Some(structure) = structure_cache.get(&parent) {
                structure.clone()
            } else {
                metrics.ancestor_rows = metrics.ancestor_rows.saturating_add(1);
                let row = read
                    .block_structure(parent)
                    .map_err(|_| ManagedSparseTaskQueryFallback::Structure)?
                    .ok_or(ManagedSparseTaskQueryFallback::Structure)?;
                if row.block_id != parent {
                    return Err(ManagedSparseTaskQueryFallback::Structure);
                }
                let structure = ManagedSparseTaskQueryStructure {
                    page_id: row.page_id,
                    parent: row.parent,
                    order: row.order,
                };
                structure_cache.insert(parent, structure.clone());
                structure
            }
        };
    }
    Ok(sparse_task_query_dfs_key(leaf_to_root))
}

struct ManagedLocalPublisherAttempt {
    batch_id: BatchId,
    authorship_complete: bool,
    provider_complete: bool,
    requested_authorship: Option<ManagedLocalDerivativeAuthority>,
    requested_provider: Option<ManagedLocalDerivativeAuthority>,
}

impl ManagedLocalDerivativePublisher for ManagedLocalPublisherAttempt {
    fn ensure_local_authorship(
        &mut self,
        authority: &ManagedLocalDerivativeAuthority,
    ) -> ManagedLocalPublicationState {
        if authority.batch_id != self.batch_id {
            return ManagedLocalPublicationState::Conflict(
                "derivative authorship authority names another journal batch".into(),
            );
        }
        if self.authorship_complete {
            ManagedLocalPublicationState::Complete
        } else {
            self.requested_authorship = Some(authority.clone());
            ManagedLocalPublicationState::Pending(
                "runtime authorship owner will adopt the accepted record".into(),
            )
        }
    }

    fn ensure_provider_publication(
        &mut self,
        authority: &ManagedLocalDerivativeAuthority,
    ) -> ManagedLocalPublicationState {
        if authority.batch_id != self.batch_id {
            return ManagedLocalPublicationState::Conflict(
                "derivative provider authority names another journal batch".into(),
            );
        }
        if self.provider_complete {
            ManagedLocalPublicationState::Complete
        } else {
            self.requested_provider = Some(authority.clone());
            ManagedLocalPublicationState::Pending(
                "runtime provider owner will publish the accepted frontier".into(),
            )
        }
    }
}

#[cfg(test)]
thread_local! {
    /// Counts the parser fallback inside `application_from_trusted_local_commit`.
    /// A direct durable foreground outcome carries a parser-owned DTO and must
    /// not enter this fallback; projection/recovery outcomes intentionally do.
    static TRUSTED_LOCAL_RESPONSE_PARSE_FALLBACKS: std::cell::Cell<usize> = const {
        std::cell::Cell::new(0)
    };
}

#[cfg(test)]
fn reset_trusted_local_response_parse_fallbacks() {
    TRUSTED_LOCAL_RESPONSE_PARSE_FALLBACKS.with(|counter| counter.set(0));
}

#[cfg(test)]
fn trusted_local_response_parse_fallbacks() -> usize {
    TRUSTED_LOCAL_RESPONSE_PARSE_FALLBACKS.with(std::cell::Cell::get)
}

#[cfg(test)]
fn note_trusted_local_response_parse_fallback() {
    TRUSTED_LOCAL_RESPONSE_PARSE_FALLBACKS.with(|counter| {
        counter.set(counter.get().saturating_add(1));
    });
}

